<div class="page-actions"><div><h2>News & Blog Management</h2><p>Publish Foundation news and blog updates with professional images, SEO metadata and homepage visibility.</p></div><div class="filters"><a class="<?=($type??'')===''?'active':''?>" href="<?=url('admin/posts')?>">All</a><a class="<?=($type??'')==='news'?'active':''?>" href="<?=url('admin/posts?type=news')?>">News</a><a class="<?=($type??'')==='blog'?'active':''?>" href="<?=url('admin/posts?type=blog')?>">Blog</a></div></div>
<div class="management-layout"><section class="admin-panel sticky-form"><div class="panel-head"><h3>Post Editor</h3><button class="outline-link mini" type="button" data-post-reset>New Post</button></div><form method="post" enctype="multipart/form-data" action="<?=url('admin/posts/save')?>" class="admin-form" data-post-form><?=csrf_field()?><input type="hidden" name="id"><label><span>Type</span><select name="post_type"><option value="news">News</option><option value="blog">Blog</option></select></label><label><span>Status</span><select name="status"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><label class="full"><span>Title *</span><input name="title" required maxlength="200"></label><label class="full"><span>Excerpt / Summary</span><textarea name="excerpt" rows="3" maxlength="800"></textarea></label><label class="full"><span>Article Content</span><textarea name="content" rows="12" maxlength="50000" placeholder="Write clear, accessible article content here."></textarea></label><label><span>Publish Date & Time</span><input type="datetime-local" name="published_at"></label><label><span>Featured Image</span><input type="file" name="featured_image" accept=".jpg,.jpeg,.png,.webp"><small class="helper">Recommended 1200 × 675 px (16:9). Automatically cover-fitted.</small></label><label class="toggle-line full"><input type="checkbox" name="is_featured" value="1"><span>Feature prominently on homepage</span></label><div class="form-divider full"><b>SEO & AEO</b></div><label class="full"><span>SEO Title</span><input name="meta_title" maxlength="240"></label><label class="full"><span>Meta Description</span><textarea name="meta_description" rows="3" maxlength="500"></textarea></label><button class="admin-btn full">Save Post</button></form></section>
<section class="content-card-list"><?php foreach($posts as $p):$dt=$p['published_at']?date('Y-m-d\TH:i',strtotime($p['published_at'])):'';$payload=e(json_encode(['id'=>$p['id'],'post_type'=>$p['post_type'],'title'=>$p['title'],'excerpt'=>$p['excerpt'],'content'=>$p['content'],'status'=>$p['status'],'is_featured'=>(int)$p['is_featured'],'published_at'=>$dt,'meta_title'=>$p['meta_title'],'meta_description'=>$p['meta_description']],JSON_HEX_APOS|JSON_HEX_QUOT));?><article class="admin-panel post-admin-card"><?php if($p['featured_image']):?><img src="<?=e(public_upload($p['featured_image']))?>" alt=""><?php else:?><div class="post-placeholder">97</div><?php endif;?><div class="post-admin-copy"><span class="eyebrow green-text"><?=e(strtoupper($p['post_type']))?></span><h3><?=e($p['title'])?></h3><p><?=e(mb_strimwidth($p['excerpt']?:strip_tags($p['content']??''),0,130,'…'))?></p><small><?=e($p['published_at']?date('d M Y · H:i',strtotime($p['published_at'])):'Not scheduled')?> · <?=e(ucfirst($p['status']))?><?=$p['is_featured']?' · Featured':''?></small></div><div class="card-admin-actions"><button class="outline-link" type="button" data-post-edit='<?=$payload?>'>✎ Edit</button><?php if($p['status']==='published'):?><a class="outline-link" target="_blank" href="<?=url('news/'.$p['slug'])?>">View ↗</a><?php endif;?><form method="post" action="<?=url('admin/posts/delete')?>" data-confirm="Delete this post permanently?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="danger-link">Delete</button></form></div></article><?php endforeach;?><?php if(!$posts):?><div class="admin-panel empty-card">No news or blog posts found.</div><?php endif;?><?=admin_pagination($pagination??[])?></section></div>
